Rewrite the following GNU C++14 code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to rewrite:
<original_code>
#include <iostream>
#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <algorithm>
#include <vector>
#include <cmath>
using namespace std;

long long x,y,n;

long long gcd(long long a,long long b){
    return (b==0)? a:gcd(b,a % b);
}

int main(){

    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    cin >> x >> y >> n;

    if (y<=n){
        long a=gcd(x,y);
        x=x/a;y=y/a;
        cout << x << "/" << y;
        return 0;
    }
    if (x==y){
        cout << "1/1";
        return 0;
    }

    double ans=1e18;
    double xy=double(x)/double(y);
    long long ansx,ansy;
    long long l=0,r=y;
    for (long long i=1;i<=n;i++){
        while (i*x>r){l+=y;r+=y;}
        if (i*x>=l && i*x<=r) {
            long long ll=l/y;
            long long rr=r/y;
            double li=double(ll)/double(i);
            double ri=double(rr)/double(i);
            double tmp1=abs(xy-li);
            double tmp2=abs(xy-ri);
            if (tmp2<tmp1){
                if ((float)tmp2<(float)ans){
                    ans=tmp2;
                    ansx=rr;
                    ansy=i;
                }
            }else{
                if ((float)tmp1<(float)ans){
                    ans=tmp1;
                    ansx=ll;
                    ansy=i;
                }
            }
        }
    }

    long long a=gcd(ansx,ansy);
    ansx/=a;ansy/=a;
    cout << ansx << "/" << ansy;

    return 0;

}

</original_code>
